// Rule-based relational checks. No comparison of table names or sample-row guesses.
export const setEqual=(a,b)=>Array.isArray(a)&&Array.isArray(b)&&new Set(a).size===a.length&&new Set(b).size===b.length&&a.length===b.length&&a.every(x=>b.includes(x));
export function closure(attrs,fds){const out=new Set(attrs);let n;do{n=out.size;for(const d of fds)if(d.from.every(a=>out.has(a)))d.to.forEach(a=>out.add(a));}while(n!==out.size);return out;}
export function subsets(attrs){return Array.from({length:2**attrs.length},(_,n)=>attrs.filter((_,i)=>n&(1<<i))).sort((a,b)=>a.length-b.length);}
export function projectedDependencies(attrs,fds){const out=[];for(const from of subsets(attrs)){const c=closure(from,fds);for(const a of attrs)if(!from.includes(a)&&c.has(a)&&!out.some(d=>d.to[0]===a&&d.from.every(x=>from.includes(x))))out.push({from,to:[a]});}return out;}
export function candidateKeys(attrs,fds){const out=[];for(const s of subsets(attrs))if(!out.some(k=>k.every(a=>s.includes(a)))&&attrs.every(a=>closure(s,fds).has(a)))out.push(s);return out;}
export function losslessJoin(tables,attrs,fds){
 const parent=new Map(),find=x=>{if(!parent.has(x))parent.set(x,x);if(parent.get(x)!==x)parent.set(x,find(parent.get(x)));return parent.get(x);};
 const merge=(x,y)=>{x=find(x);y=find(y);if(x===y)return false;if(y.startsWith('a'))[x,y]=[y,x];parent.set(y,x);return true;};
 const rows=tables.map((t,i)=>attrs.map((a,j)=>t.attributes.includes(a)?'a'+j:'b'+i+'-'+j));let changed;
 do{changed=false;for(const d of fds)for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++)if(d.from.every(a=>find(rows[i][attrs.indexOf(a)])===find(rows[j][attrs.indexOf(a)])))for(const a of d.to)changed=merge(rows[i][attrs.indexOf(a)],rows[j][attrs.indexOf(a)])||changed;}while(changed);
 return rows.some(r=>r.every((x,j)=>find(x)===find('a'+j)));
}
export function analyseTable(t,fds){const deps=projectedDependencies(t.attributes,fds),keys=candidateKeys(t.attributes,fds),prime=new Set(keys.flat());return {deps,keys,partial:deps.filter(d=>!prime.has(d.to[0])&&keys.some(k=>d.from.length<k.length&&d.from.every(a=>k.includes(a)))),transitive:deps.filter(d=>!prime.has(d.to[0])&&!t.attributes.every(a=>closure(d.from,fds).has(a)))};}
const phrase=d=>d.from.join(' + ')+' determines '+d.to.join(', ');
export function gradeKeyAndDependencies(original,key,deps){const errors=[],fds=original.dependencies,keys=candidateKeys(original.attributes,fds);if(!keys.some(k=>setEqual(k,key)))errors.push('The selected key is not a minimal candidate key. Check which attributes cannot be obtained from other attributes.');
 const valid=[];for(const d of deps){if(!d.from.length||!d.to.length||[...d.from,...d.to].some(a=>!original.attributes.includes(a))||d.to.some(a=>d.from.includes(a))){errors.push('Each arrow needs a determinant and different dependent attributes from this relation.');continue;}if(!d.to.every(a=>closure(d.from,fds).has(a))){errors.push(phrase(d)+' is not supported by the business rules.');continue;}
 const prime=new Set(keys.flat()),isPartial=d.to.every(a=>!prime.has(a)&&keys.some(k=>d.from.length<k.length&&d.from.every(x=>k.includes(x)))),isTransitive=d.from.some(a=>!prime.has(a))&&!original.attributes.every(a=>closure(d.from,fds).has(a)),isFull=keys.some(k=>setEqual(k,d.from))&&d.to.every(a=>!subsets(d.from).some(s=>s.length<d.from.length&&closure(s,fds).has(a)));
 if((d.kind==='partial'&&!isPartial)||(d.kind==='transitive'&&!isTransitive)||(d.kind==='full'&&!isFull))errors.push('Recheck the classification of '+phrase(d)+'. An implied whole-key arrow is not necessarily a full dependency.');valid.push(d);}
 for(const d of fds)if(!d.to.every(a=>closure(d.from,valid).has(a)))errors.push('Your arrows do not yet express the rule: '+phrase(d)+'.');return {passed:!errors.length,errors,checks:!errors.length?['Candidate key and dependency coverage are correct.']:[]};}
export function gradeDecomposition(original,tables,stage=3){const errors=[],checks=[],fds=original.dependencies,attrs=original.attributes;
 if(![2,3].includes(stage)||!Array.isArray(tables)||!tables.length||tables.length>12)return {passed:false,errors:['Create between one and twelve tables and choose 2NF or 3NF.'],checks:[]};
 const ids=new Set(),names=new Set(),signatures=new Set();let projected=[];
 for(const t of tables){if(!t.id||ids.has(t.id))errors.push('Every table needs a unique identifier.');ids.add(t.id);const name=t.name?.trim().toLowerCase();if(!name||names.has(name))errors.push('Give every table a different name.');names.add(name);if(!Array.isArray(t.attributes)||!t.attributes.length||new Set(t.attributes).size!==t.attributes.length||t.attributes.some(a=>!attrs.includes(a))){errors.push((t.name||'A table')+': select original attributes, without duplicates.');continue;}const sig=[...t.attributes].sort().join('|');if(signatures.has(sig))errors.push(t.name+': this duplicates another table.');signatures.add(sig);
 const a=analyseTable(t,fds);projected.push(...a.deps);if(!Array.isArray(t.key)||!a.keys.some(k=>setEqual(k,t.key)))errors.push(t.name+': the chosen primary key must be a minimal candidate key for these attributes.');
 const violations=stage===2?a.partial:a.transitive;for(const d of violations.slice(0,3))errors.push(t.name+': '+phrase(d)+(stage===2?' depends on only part of a candidate key. Move those facts into a separate table.':' has a non-key determinant. Separate that determinant and its facts for 3NF.'));
 }
 const missing=attrs.filter(a=>!tables.some(t=>t.attributes?.includes(a)));if(missing.length)errors.push('Missing attributes: '+missing.join(', ')+'. Keep every original fact.');else checks.push('All original attributes are retained.');
 if(errors.some(s=>/select original|unique identifier/.test(s)))return {passed:false,errors:[...new Set(errors)],checks};
 if(!missing.length){if(losslessJoin(tables,attrs,fds))checks.push('The decomposition has a lossless join under the stated dependencies.');else errors.push('The join is lossy: these tables can create spurious combinations or lose associations. Retain a relation connecting the complete original key and join through shared determinants.');}
 for(const d of fds)if(!d.to.every(a=>closure(d.from,projected).has(a)))errors.push('Dependency not preserved across the tables: '+phrase(d)+'.');
 const edges=new Map(tables.map(t=>[t.id,new Set()]));for(const t of tables)for(const f of t.foreign||[]){const target=tables.find(p=>p.id===f.target);if(!target||target.id===t.id||!setEqual(f.attributes||[],target.key||[])||!f.attributes.every(a=>t.attributes.includes(a))){errors.push(t.name+': a foreign-key link must contain the complete selected primary key of another table, using the shared attributes.');continue;}edges.get(t.id).add(target.id);edges.get(target.id).add(t.id);}
 const seen=new Set(),visit=id=>{if(seen.has(id))return;seen.add(id);for(const next of edges.get(id)||[])visit(next);};visit(tables[0].id);if(seen.size!==tables.length)errors.push('Add valid foreign-key links to connect the resulting tables. Do not delete the attributes needed for these links.');else checks.push('The declared foreign-key links connect the tables.');
 if(!errors.length)checks.push('Keys, dependency preservation and '+stage+'NF are correct. Equivalent table names and valid alternative decompositions are accepted.');return {passed:!errors.length,errors:[...new Set(errors)],checks};}
